# Helper for raw pty testing with isolated env and temp dirs
import os, subprocess, select, time, struct, fcntl, termios, pty, tempfile, shutil

def run_felix(cmd_args, keys, width=100, height=30, cwd="/workspace", env_extra=None, timeout_per_key=0.6):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", height, width, 0, 0))
    env = dict(os.environ)
    env['TERM'] = 'xterm-256color'
    if env_extra:
        env.update(env_extra)
    # Use setsid to isolate?
    p = subprocess.Popen(["./executable"]+cmd_args, stdin=slave, stdout=slave, stderr=slave, env=env, cwd=cwd, preexec_fn=os.setsid)
    os.close(slave)
    time.sleep(0.7)
    def drain(duration=0.5):
        out=b""
        end=time.time()+duration
        while time.time()<end:
            r,_,_=select.select([master],[],[],0.1)
            if r:
                try:
                    data=os.read(master, 65536)
                    if data: out+=data
                    else: break
                except OSError: break
        return out
    results=[]
    initial = drain(0.7)
    results.append(("INITIAL", initial))
    for label, k in keys:
        if isinstance(k, str): k=k.encode()
        try:
            os.write(master, k)
        except OSError as e:
            results.append((label, f"write err {e}".encode()))
            break
        time.sleep(timeout_per_key)
        out = drain(0.4)
        results.append((label, out))
        # check if process exited
        if p.poll() is not None:
            # drain remaining
            extra = drain(0.3)
            results.append(("EXITED code="+str(p.returncode), extra))
            break
    try:
        if p.poll() is None:
            p.terminate()
            try: p.wait(timeout=1)
            except: p.kill()
    except: pass
    try: os.close(master)
    except: pass
    return results

def show(results, maxlen=6000):
    for label, data in results:
        print(f"=== {label} ({len(data)} bytes) ===")
        print(repr(data[:maxlen]))
        if len(data)>maxlen:
            print(f"... truncated {len(data)-maxlen} more")
        print()

if __name__ == "__main__":
    import sys
    # quick test
    res = run_felix(["./assets"], [("j", b"j")])
    show(res)
