def get_terminal_size_fallback():
    # Try ioctl on stdout, stderr, stdin
    for fd in (sys.stdout.fileno() if hasattr(sys.stdout, 'fileno') else -1,
               sys.stderr.fileno() if hasattr(sys.stderr, 'fileno') else -1,
               sys.stdin.fileno() if hasattr(sys.stdin, 'fileno') else -1):
        try:
            if fd < 0:
                continue
            res = fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH", 0, 0, 0, 0))
            h, w, _, _ = struct.unpack("HHHH", res)
            if w != 0 and h != 0:
                return (w, h)
        except Exception:
            continue
    # No ioctl success: check TERM
    if "TERM" not in os.environ:
        return None
    # Use COLUMNS/LINES or default 80x24
    def parse_env(name, default):
        v = os.environ.get(name)
        if v is None:
            return default
        try:
            iv = int(v)
            if iv <= 0:
                return default
            return iv
        except:
            return default
    w = parse_env("COLUMNS", 80)
    h = parse_env("LINES", 24)
    return (w, h)

def cli_handle_path(path, use_log):
    # Check exists then isdir
    exists = os.path.exists(path)
    if not exists:
        sys.stdout.write("\n")
        sys.stdout.flush()
        sys.stderr.write(f"Invalid path: {path}\n`fx -h` shows help.\n")
        sys.stderr.flush()
        return 0
    isdir = os.path.isdir(path)
    if not isdir:
        sys.stderr.write("Path should be directory.\n`fx -h` shows help.\n")
        sys.stderr.flush()
        return 0
    return run_tui(path, use_log)

def main_cli():
    args = sys.argv[1:]
    n = len(args)
    if n == 0:
        return run_tui(os.getcwd(), False)
    elif n == 1:
        a = args[0]
        if a in ("-h", "--help"):
            sys.stdout.write(HELP_TEXT)
            sys.stdout.flush()
            return 0
        elif a == "--init":
            sys.stdout.write(INIT_TEXT)
            sys.stdout.flush()
            return 0
        elif a in ("-l", "--log"):
            return run_tui(os.getcwd(), True)
        else:
            return cli_handle_path(a, False)
    elif n == 2:
        a0, a1 = args
        if a0 in ("-h", "--help", "--init"):
            sys.stdout.write(HELP_TEXT)
            sys.stdout.flush()
            return 0
