def zstd_decompress(data):
    lib = get_zstd_lib()
    if lib is None:
        raise Exception("zstd not available")
    import ctypes
    # Try streaming decompress to handle unknown size
    try:
        # Use streaming API if available
        if hasattr(lib, "ZSTD_createDStream"):
            dstream = lib.ZSTD_createDStream()
            if not dstream:
                raise Exception("createDStream failed")
            try:
                ret = lib.ZSTD_initDStream(dstream)
                if lib.ZSTD_isError(ret):
                    raise Exception(lib.ZSTD_getErrorName(ret).decode())
                # Prepare input
                in_buf = lib._inBuffer()
                # Need to keep data alive
                c_data = (ctypes.c_char * len(data)).from_buffer_copy(data)
                in_buf.src = ctypes.cast(c_data, ctypes.c_void_p)
                in_buf.size = len(data)
                in_buf.pos = 0
                out_chunks = []
                # Use 1MB out buffer repeatedly
                OUT_SIZE = 1024*1024
                while True:
                    out_buf_obj = ctypes.create_string_buffer(OUT_SIZE)
                    out_buf = lib._outBuffer()
                    out_buf.dst = ctypes.cast(out_buf_obj, ctypes.c_void_p)
                    out_buf.size = OUT_SIZE
                    out_buf.pos = 0
                    ret = lib.ZSTD_decompressStream(dstream, ctypes.byref(out_buf), ctypes.byref(in_buf))
                    if lib.ZSTD_isError(ret):
                        raise Exception(lib.ZSTD_getErrorName(ret).decode())
                    if out_buf.pos > 0:
                        out_chunks.append(bytes(out_buf_obj.raw[:out_buf.pos]))
                    if ret == 0:
