                        break
                return b"".join(out_chunks)
            finally:
                try:
                    lib.ZSTD_freeDStream(dstream)
                except:
                    pass
        else:
            # Fallback: try large buffer
            for sz in [len(data)*10+1024, 10*1024*1024, 50*1024*1024]:
                dst = ctypes.create_string_buffer(sz)
                ret = lib.ZSTD_decompress(dst, sz, data, len(data))
                if not lib.ZSTD_isError(ret):
                    return bytes(dst.raw[:ret])
            raise Exception("decompress failed")
    except Exception as e:
        # Fallback to large buffer method
        for sz in [len(data)*10+1024, 10*1024*1024]:
            try:
                dst = ctypes.create_string_buffer(sz)
                ret = lib.ZSTD_decompress(dst, sz, data, len(data))
                if not lib.ZSTD_isError(ret):
                    return bytes(dst.raw[:ret])
            except:
                continue
        raise e

